// EN translation FIRST PASS. Literary editorial approval outstanding.
const OUTCOMES_EN_E051_E100 = Object.freeze({"E051.1":{"s":"The huntress takes the egg with both hands and examines the cracks in the shell for a long time. Because you didn't bargain, she counts out the gold."},"E051.2":{"s":"You name a price higher than the proposed one, and the huntress, after a heavy pause, agrees. The coins go to the party, the egg remains under her protection.","f":"The huntress notices that you are trying to profit from the clutch, and calls her relatives. The conversation is interrupted by the beginning of a skirmish."},"E051.3":{"s":"{{heroName}} arranges to escort the huntress to a safe road. She rewards the help with gold and travel provisions.","f":"{{heroName}} offers the hunter protection, but she does not trust someone else’s party. You part ways without a deal."},"E051.4":{"s":"While the huntress is distracted, you remove the heavy egg from the fire pit. The loot brings gold to the party.","f":"When you pick up the egg, the huntress makes a sharp call, and armed draconians answer from the slopes. The battle begins."},"E052.1":{"s":"The exile kneels and takes the oath without a single reservation. A young draconian joins the party.","f":"The exile cannot bear questions about his past and leaves after the shared meal. The party's provisions dwindle.","v":{"rs":"You are ready to accept the exile, but there is no free space for a new fighter. As a farewell, the draconian leaves you some gold."}},"E052.2":{"s":"The test match ends without a fatal blow. Convinced of your determination, the draconian swears an oath to the party.","f":"The test goes out of control: {{affectedHeroName}} is gravely wounded. The Draconid never takes the oath.","v":{"rs":"The duel convinces the exile of your strength, but he cannot join the party. Instead of an oath, he gives you gold.","nf":"The match is interrupted before any of the available fighters are wounded. The oath was never taken."}},"E052.3":{"s":"{{heroName}} holds firm in the duel, then extends a hand to the defeated opponent. The draconian accepts a place in your party.","f":"The Draconid deals the final blow, and {{affectedHeroName}} is severely wounded. The strength check ends without a new ally.","v":{"rs":"{{heroName}} deserves the respect of the draconian, but there is no place for him in the party. The exile leaves gold as a token of recognition.","nf":"The duel ends without serious injuries, but the draconian does not accept the proposed oath."}},"E052.4":{"s":"You refuse the exile without asking him for proof. He bows briefly and leaves to look for another party."},"E053.1":{"s":"The collector counts sixteen gold coins and steps back from the road. The passage is open, although the purse has become lighter."},"E053.2":{"s":"Instead of coins, you give part of the provisions to the collectors. The draconians accept the payment and let the party through."},"E053.3":{"s":"You force the collectors to admit that the right to tribute has not been proven here. To close the dispute, they pay the party gold.","f":"The collectors refuse to discuss their rights and take up arms. A skirmish begins."},"E053.4":{"s":"{{heroName}} notices an error in the collectors’ calculations and demands that the excess be returned. The Draconids reluctantly give up the gold.","f":"The collectors discover a duty missing from {{heroName}}'s calculations and charge it to the party. Your treasury loses gold."},"E054.1":{"s":"The Draconid Watch pays for your silence and points the way away from the cave. You leave with the gold without disturbing the sleeping dragon."},"E054.2":{"s":"You demand double payment, and the watchmen, looking at the entrance to the cave, give in. The party ends up with the gold.","f":"The watchmen consider your demands a threat to the secret of the cave and block the exit. A skirmish begins."},"E054.3":{"s":"You slip past the patrol and pick up the gold and supplies left behind from the side grotto. The ancient dragon does not wake up.","f":"A stone crumbles underfoot, and the roar wakes up the inhabitants of the cave. The path to the exit is blocked - the battle begins."},"E054.4":{"s":"{{heroName}} disassembles protective signs and finds a passage to the hidden gold. The seals remain intact.","f":"One of the signs flashes when {{heroName}} tries to read it. {{affectedHeroName}} is gravely wounded.","v":{"nf":"The protective seal is triggered, but among the available fighters no one is gravely wounded. The cache remains sealed."}},"E055.1":{"s":"For the coins you pay, the beastmen give you two bundles of travel food. The parties disperse without arguing about the right to a watering hole."},"E055.2":{"s":"The joint hunt takes place without quarrels, and the beastmen share the prey. The party receives supplies.","f":"The hunters quarrel over their share of the prey and accuse you of cheating. The dispute erupts into a skirmish."},"E055.3":{"s":"{{heroName}} assigns each party their own time by the water and ends the dispute. Grateful beastmen share supplies and gold.","f":"{{heroName}} proposes a schedule, but both sides insist on reaching the water first. The dispute remains unresolved."},"E055.4":{"s":"You take the watering hole by force, and the beastmen retreat into the thicket. The supplies they left behind go to the party.","f":"The beast people do not retreat: neighboring clans respond to the call. Instead of a quick capture, a battle begins."},"E056.1":{"s":"You pass the hunting test without damaging a single trophy. The elders of the beastmen give you the gold.","f":"The test ends with an unsuccessful throw: {{affectedHeroName}} is gravely wounded. Trophies remain on the tree.","v":{"nf":"The trial ends in failure, but none of the eligible fighters suffers a grave wound. The hunters offer no reward."}},"E056.2":{"s":"{{heroName}} hunts down the most dangerous prey and returns with a trophy. The beast people recognize success and pay in gold.","f":"The trail leads {{heroName}} straight to armed hunters who do not want to give up their prey. A skirmish begins."},"E056.3":{"s":"You manage to remove the most valuable antlers from the branches and take them to the merchants. The proceeds replenish the treasury.","f":"While you are cutting the trophies, their owners are returning. The beastmen grab their weapons and a skirmish begins."},"E056.4":{"s":"You leave the trophy tree untouched. The beast people follow the party with wary glances, but do not pursue."},"E057.1":{"s":"The wolf mercenary counts the payment, checks the fastening of the sword and stands next to your fighters. The agreement is concluded.","v":{"rs":"The wolf mercenary is willing to serve, but your ranks have no room for him. He compensates you in gold instead."}},"E057.2":{"s":"After a short bargaining, the beastman agrees to a smaller amount and sheathes his sword. The party has a new mercenary.","f":"The wolf mercenary rejects the offered price, but does not return the bargaining fee. The party leaves without a new fighter.","v":{"rs":"The beastman agrees to the price, but there is no room for him. Instead of joining a party, you receive gold."}},"E057.3":{"s":"{{heroName}} survives the test match and does not finish off the fallen opponent. The wolf mercenary recognizes the party as worthy and joins it.","f":"The wolf mercenary turns out to be more experienced: {{affectedHeroName}} is gravely wounded in a duel. The service contract has not been concluded.","v":{"rs":"{{heroName}} passes the mercenary test, but he cannot join the party. He gives gold instead of the promised service.","nf":"The duel ends without any eligible fighter suffering a grave wound. The mercenary refuses the contract."}},"E057.4":{"s":"You refuse to pay for someone else's self-confidence. The wolf mercenary grins and goes to look for a new employer."},"E058.1":{"s":"You place bags of provisions in front of the camp. The beastmen take their share and disappear into the darkness without a fight."},"E058.2":{"s":"The leader takes the gold and calls the pack away from your fires. The camp remains intact, though your treasury is lighter."},"E058.3":{"s":"The fighters make such a noise with their shields and cauldrons that the pack mistakes the camp for a large garrison. The beastmen retreat.","f":"The leader sees through your trick and answers with a real battle howl. The pack charges the camp: a skirmish begins."},"E058.4":{"s":"{{heroName}} strengthens the approaches to the fires, and the flock does not dare to approach. After a night of alarm, the party finds supplies left by the beastmen.","f":"{{heroName}} does not have time to close the last passage in the fence. Part of the flock breaks through and a skirmish begins."},"E058.5":{"s":"You give the order to attack before the flock closes the ring. The party leaves the camp towards a big battle."},"E059.1":{"s":"The herbalist weighs out dried meat and bundles of herbs in return for the agreed gold. The provisions go into your wagons."},"E059.2":{"s":"You find a rare bone among old animal remains, and the herbalist pays with meat and gold.","f":"The search lasts until nightfall, but the rare bone is nowhere to be found. The party has used up supplies for nothing."},"E059.3":{"s":"{{heroName}} shows the herbalist the place of the old burial of the beast. For an accurate clue, she gives the party supplies.","f":"{{heroName}} does not find reliable signs of the desired bone. The herbalist refuses the reward."},"E059.4":{"s":"You distract the herbalist with conversation and take away a bag of dried meat. Supplies end up in the wagon train.","f":"The herbalist notices a hand at her counter and loudly calls out to her relatives. A skirmish begins."},"E060.1":{"s":"The tracks lead you to a camp where beastmen exchange meat for coins. The party leaves with gold and supplies.","f":"You arrive at the camp in the midst of alarm, and the sentries mistake you for raiders. A skirmish begins."},"E060.2":{"s":"You catch up with the convoy and receive part of its supplies in exchange for help with the road. Your supplies are replenished.","f":"The convoy has too many armed guards, and attempting to approach causes general anxiety. The battle begins."},"E060.3":{"s":"{{heroName}} distinguishes traces of porters and wheels on the ground, bypassing other people's patrols. You find gold and supplies left behind.","f":"{{heroName}} follows false tracks until dusk, when it becomes clear the convoy took another road. You return without spoils."},"E060.4":{"s":"You walk around a trampled valley along a dry slope. You don’t get either other people’s warehouses or other people’s blades."},"E061.1":{"s":"You lift the lid of the chest as the light in the guardian's core is nearly extinguished. There are gold coins inside.","f":"The lid slides open and the stone-metal guard instantly straightens up. He blocks the road, starting a skirmish."},"E061.2":{"s":"Given a share of your supplies, the ancient mechanism stirs and opens the chest. The rescued core yields gold in thanks."},"E061.3":{"s":"{{heroName}} changes the order of the runes on the guard's armor, and he opens a chest with gold and warehouse supplies.","f":"The mechanism mistakes {{heroName}}'s command for an intrusion and snaps its stone hand shut. {{affectedHeroName}} is gravely wounded.","v":{"nf":"The guard blocks the reconfiguration attempt, but among the available fighters, no one is gravely wounded. The chest remains closed."}},"E061.4":{"s":"You walk past the stationary guard without touching the chest. A faint glow from the core remains behind."},"E062.1":{"s":"You block the road, and the column halts to await fresh orders. A cargo crate left behind holds supplies.","f":"Constructs perceive attempts to stop them as a hostile order. The column reforms for a skirmish."},"E062.2":{"s":"Following the mechanical formation, you find a locked warehouse with no guards. The gold of the previous owners remains inside.","f":"The column leads you to a long-emptied warehouse. While you are looking for another way, supplies are running out."},"E062.3":{"s":"{{heroName}} reads the faded command rune and indicates where the constructs left the cargo. The party takes gold and supplies.","f":"{{heroName}} does not find the end of the ancient command, and the column continues to march. You don't see the promised warehouse."},"E062.4":{"s":"You let the convoy pass without asking questions. The last construct repeats the order and disappears around the corner."},"E063.1":{"s":"The crystals are separated from the shattered body without damage. Their value turns into gold for the party.","f":"As soon as you touch the crystal, the damaged golem emits a residual discharge. {{affectedHeroName}} is gravely wounded.","v":{"nf":"The golem releases a residual discharge, but there are no casualties among the available fighters. The crystals remain in the case."}},"E063.2":{"s":"You ease the surviving core from the shattered golem's chest. Buyers pay a handsome price in gold for it.","f":"As soon as you free the core, neighboring constructs recognize the disassembly attempt as an attack. A skirmish begins."},"E063.3":{"s":"{{heroName}} secures split slabs and consistently removes valuable parts. Dismantling brings gold without new damage.","f":"{{heroName}} discovers a damaged fastening beneath the armour that cannot be opened without breaking the core. The salvage ends empty-handed."},"E063.4":{"s":"You connect the scraps of conductors, and the broken golem rises to its feet. The restored construct joins the party.","f":"The awakened golem does not recognize the saviors and raises its stone fists. A skirmish begins.","v":{"rs":"The golem's core glows once more, but there is no room for the restored construct in your party. You receive gold for the useful parts."}},"E064.1":{"s":"After several attempts, the runes flash in the correct order and the bridge rises. At its base you find supplies abandoned.","f":"An incorrect sequence extinguishes the runes, and the bridge remains below. Some of the supplies are spent on fruitless waiting."},"E064.2":{"s":"{{heroName}} deciphers the ancient runes and raises the bridge. On the far bank, you gather supplies.","f":"{{heroName}} cannot parse the erased character, so the mechanism does not respond. The party is left without a find."},"E064.3":{"s":"{{heroName}} rests against the jammed beam and lifts the span manually. The party crosses the bridge without touching the ancient runes.","f":"The beam snaps from its support and crushes {{affectedHeroName}}, inflicting a grave wound.","v":{"nf":"The beam falls, but no one among the available fighters is gravely wounded. The bridge remains unraised."}},"E064.4":{"s":"You break the lifting mechanism and take away the valuable metal parts found in it. They bring gold to the party.","f":"The destruction triggers protective runes, and armed constructs emerge from the bridge supports. A skirmish begins."},"E065.1":{"s":"You remove the minted coins from the belt before the mechanical arm can remove them. The gold is sent to the treasury.","f":"The workshop notices the disappearance of finished parts and releases watchdog mechanisms. A skirmish begins."},"E065.2":{"s":"You switch machines to the production of dry road rations. Instead of parts, supplies appear on the tape.","f":"The machines chew on the fed materials and stop. An attempt to reconfigure costs some supplies."},"E065.3":{"s":"{{heroName}} aligns gears and changes the order of operations on the control panel. The workshop gives out gold and supplies.","f":"{{heroName}} finds a broken gear that cannot be replaced. Production remains the same."},"E065.4":{"s":"You stop the machines and remove some valuable coin plates from the panel. The workshop finally quiets down."},"E066.1":{"s":"You release the glowing core and place it in a suitable housing. The small construct accepts a new assignment and joins the party.","f":"An attempt to transfer the core ends in broken mounts and repair costs. You lose gold, but the construct remains in ruins.","v":{"rs":"The core can be saved, but the new construct cannot join the party. You receive gold for the remaining working parts."}},"E066.2":{"s":"You sell the sentient core to an artefact dealer. Instead of the new role it was promised, your treasury receives gold."},"E066.3":{"s":"{{heroName}} restores the core's memories, and it chooses to serve your party. You also salvage supplies from the discarded shell.","f":"{{heroName}} cannot recover the damaged memories; the core falls silent again. You leave without a new ally.","v":{"rs":"{{heroName}} restores the core's memories, but there is no room for another ally. You salvage useful parts and supplies instead."}},"E066.4":{"s":"You leave the core alone and leave a small construct among the rubble. Its indicator accompanies the party to the turn."},"E067.1":{"s":"The deer leads the party to a clearing where they can collect edible roots and berries. Supplies are replenished, and the beast disappears between the trees.","f":"The deer leads you away from the road and then disappears into the thicket. Supplies are consumed on the return journey."},"E067.2":{"s":"You approach the white deer and remove the gold chains from the antlers. Their value replenishes the treasury.","f":"The deer suddenly lowers its antlers in defense of itself, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The white stag drives you back, but none of the eligible fighters is gravely wounded. Its golden chains remain on its antlers."}},"E067.3":{"s":"{{heroName}} keeps his distance and reads the tracks without disturbing the deer. The path leads to supplies and abandoned gold.","f":"{{heroName}} loses track among roots and old hoof prints. The white deer disappears without leaving any prey."},"E067.4":{"s":"You let the white deer pass and leave the gold chains alone. The animal slowly walks away along the road without looking back."},"E068.1":{"s":"You quietly pull the nearby bags out from under the broken cart. The bear does not wake up, but the supplies go to the party.","f":"One of the bags hits a stone, and the animal wakes up from the sound. A skirmish begins at the entrance to the den."},"E068.2":{"s":"You venture deeper into the cave and discover the caravan's lost strongbox alongside its provisions. You carry away gold and supplies.","f":"Heavy breathing is suddenly heard right behind you, and the passage from the cave is already closed. The battle begins."},"E068.3":{"s":"{{heroName}} pins the bear back with a shield just long enough for the others to carry out the sacks. The party escapes with supplies.","f":"The bear crushes the shield and knocks {{affectedHeroName}} onto the rocks. The soldier is gravely wounded.","v":{"nf":"The beast knocks over the shield, but none of the available fighters is gravely wounded. The bags remain at the den."}},"E068.4":{"s":"You deploy your party before disturbing the cave. The looted convoy remains lying at the entrance."},"E069.1":{"s":"Raven leads the party from stone to stone to the old hiding place. Gold is found under the roots.","f":"The bird disappears behind a distant hill, leaving you off to the side of the road. Finding a way back takes up supplies."},"E069.2":{"s":"You pick up the ring and don't follow the bird. Selling the find brings in some gold."},"E069.3":{"s":"{{heroName}} recognises the mark on the ring and knows where the raven is leading. You recover gold and provisions from a forgotten cache.","f":"{{heroName}} does not recognize the worn script, and the raven flies away without waiting for an answer. There is no other reward."},"E069.4":{"s":"You scare away the raven with a wave of your cloak. The bird flies away into the forest, and the ring remains lying on the road."},"E070.1":{"s":"You throw some of the provisions on the side of the road, and the wolves switch to food. The party leaves without drawing their weapons."},"E070.2":{"s":"You maintain formation and do not change your pace until the leader stops pursuing. The wolves are gradually falling behind.","f":"The leader waits until your rear ranks fall behind, then the wolf pack charges. A skirmish begins."},"E070.3":{"s":"{{heroName}} draws the pack away with a false trail and returns with provisions found along the animals' path. The party moves on.","f":"The wolves bypass the deceptive maneuver and rush towards {{affectedHeroName}}. The fighter is gravely wounded.","v":{"nf":"The pack disrupts the diversionary maneuver, but among the available fighters, no one is gravely wounded. The party has to retreat without any loot."}},"E070.4":{"s":"You form up before the wolves can surround you. A dangerous skirmish with the pack begins."},"E071.1":{"s":"You manage to climb the rock, sort through the shiny prey and go down before the birds return. Gold replenishes the treasury.","f":"Adult birds return when the party is still on the rock. {{affectedHeroName}} dies under their blows.","v":{"nf":"The birds return and force the party to retreat, but none of the available fighters are killed. The prey remains in the nest."}},"E071.2":{"s":"You take one precious thing from the nest and manage to leave before the owners appear. The find brings gold.","f":"The very first loss attracts giant birds to the rock. They rush at the party - a skirmish begins."},"E071.3":{"s":"{{heroName}} climbs the ledges, grabs the most valuable item and returns before the birds notice the theft. The party ends up with the gold.","f":"{{heroName}} does not have time to get off the ledge before the birds return, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The birds disrupt a quick raid, but among the available fighters, no one receives a serious wound. Nothing can be taken from the nest."}},"E071.4":{"s":"You do not disturb the nest and continue along the cliff. The first distant cry of a returning bird is heard overhead."},"E072.1":{"s":"You dig up a chest from under the roots and find gold coins in it. The fox watches from the bushes without approaching.","f":"The shovel breaks on the stones, and the chest turns out to be empty. Money for new tools is wasted on useless searches."},"E072.2":{"s":"Beneath the first chest lies another hidden cache, filled with still more valuable loot. The treasure swells your gold reserves.","f":"The roots fall into the excavation and {{affectedHeroName}} is gravely wounded. It is not possible to reach the lower cache.","v":{"nf":"The deep excavation is crumbling, but among the available fighters there are no gravely wounded. The lower cache remains closed."}},"E072.3":{"s":"{{heroName}} crawls between the roots and pulls out the chest without undermining the ground around it. There is gold inside.","f":"{{heroName}} feels for an empty box under the roots and climbs back out. The suspicious fox disappears into the thicket."},"E072.4":{"s":"You leave the chest under the roots and don't follow the fox. A red tail flashes from the bushes and disappears."},"E073.1":{"s":"You step over the circle of mushrooms, and the fairies move the bag right to your feet. The coins go to the party.","f":"The circle closes behind you, forcing you to look for a way out of the clearing until the morning. The search comes at a cost of supplies."},"E073.2":{"s":"You endure the wild fairy dance and receive bundles of food as your reward. The revelry ends before anyone grows dizzy.","f":"The fairy dance accelerates until {{affectedHeroName}} falls among the glowing mushrooms, severely wounded.","v":{"nf":"The fairies dance at dangerous speeds, but none of the available fighters are gravely wounded. There are no gifts from fairies."}},"E073.3":{"s":"{{heroName}} repeats the ancient greeting, and the fairies stop circling around the bag. In gratitude they give gold and supplies.","f":"{{heroName}} cannot remember the last movement of the ritual. Fairies laugh and hide gifts."},"E073.4":{"s":"You avoid the mushroom ring. Behind you you can hear the laughter of fairies, who will have to look for other participants in the game."},"E074.1":{"s":"You leave provisions for the fairies as a peace offering. Their guard withdraws, returning with a small gift of coins."},"E074.2":{"s":"You walk along the edge of the path without touching the armored guard. The fairies see you off with angry cries.","f":"A giant ladybug blocks the passage with its shell, and the fairies raise the alarm. A skirmish begins."},"E074.3":{"s":"{{heroName}} holds the shield in front of the guard and does not strike back. The fairies recognize the intentions as peaceful and provide supplies.","f":"The guard collapses the armored shell onto the shield, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The guard knocks over the shield, but among the available fighters no one is gravely wounded. Fairies don't trust your intentions."}},"E074.4":{"s":"You break through the armored guard's defenses and take the gold jewelry from his post. The spoils go to the party.","f":"The shell withstands the attack, and the fairies call all the neighboring guards for help. The battle begins."},"E075.1":{"s":"The butterfly leads the party through a short passage between the trees and straight to a forgotten warehouse. Supplies were preserved inside.","f":"The fairy changes direction too often, and you lose it among the same paths. Supplies go on the way back."},"E075.2":{"s":"Having received the gold, the fairy draws a detailed route on the tree bark. You find a warehouse and replenish supplies without wandering again."},"E075.3":{"s":"{{heroName}} follows a path beneath the butterfly's flight and reaches the storehouse before the guide. Your party takes the supplies.","f":"{{heroName}} loses the butterfly behind the dense crowns and does not find the right turn. An empty path does not bring any loot."},"E075.4":{"s":"You thank the fairy for the offer, but remain on the familiar road. The butterfly soon disappears over the forest."},"E076.1":{"s":"The oracle accepts the payment and rearranges the seeds in the shape of a fork in the road. At her direction, the party finds supplies."},"E076.2":{"s":"The seed pattern leads you to a hidden purse. You receive gold, although the bet has already been given to the oracle.","f":"The seeds form an empty circle, and the promised luck fails to arrive. The fairy keeps the gold you staked."},"E076.3":{"s":"{{heroName}} notices a repeating sign in the seed paths and correctly interprets the prediction. The party finds gold and supplies.","f":"{{heroName}} reads the picture differently than the oracle, and the hint becomes meaningless. There is no find."},"E076.4":{"s":"You don't pay for the prediction and move on. The Oracle silently erases the paths of seeds."},"E077.1":{"s":"By dawn the enchanted seeds have grown into large edible fruits. You gather them as supplies for the road.","f":"Instead of fruits, tenacious predatory vines grow from the ground. They rush to the feet of the travelers - a skirmish begins."},"E077.2":{"s":"You plant the whole bed, and by morning the fairy garden teems with edible fruit. There is enough food for several days on the road.","f":"Too dense planting comes to life with a solid wall of predatory stems. The party has to join the battle."},"E077.3":{"s":"{{heroName}} separates harmless seeds from predatory ones even before planting. In the morning you gather a rich harvest of supplies.","f":"{{heroName}} does not find a reliable sign of safety, and sowing is postponed. The party does not receive a harvest."},"E077.4":{"s":"You give the magic seeds to the merchant without testing them yourself. He pays in gold for an unknown future harvest."},"E078.1":{"s":"The king accepts the wreath from the hands of the fairy ruler and takes an oath. In response, she hands the party gold and supplies.","f":"The wreath is tightened on the King's head, and the ancient oath burns him with a severe wound. The fairy ruler offers no reward.","v":{"nf":"The wreath flares up, but the King is not gravely wounded. The oath remains unfinished."}},"E078.2":{"s":"You ask the fairy ruler to explain the oath without riddles, and she agrees to clear terms. As a sign of agreement, you receive gold.","f":"The fairy queen takes your clarification as an insult and calls the court guard. A skirmish begins."},"E078.3":{"s":"{{heroName}} answers with his oath, not giving up the King under someone else’s conditions. The fairy queen gives the party gold and supplies.","f":"{{heroName}} can't finish the words before the circle of flowers disintegrates. Fairies do not recognize a counter-oath."},"E078.4":{"s":"You do not allow the King to wear a flower crown. The fairy ruler takes it and returns to the circle without objection."},"E079.1":{"s":"The goblin counts the coins twice and hands out the promised supplies from under the counter. The party moves away from the cart without deception."},"E079.2":{"s":"The closed box contains a cache of gold, which the goblin clearly did not expect. The purchase brings in more than it cost.","f":"The box holds nothing but dust, and the goblin demands more money for its supposedly broken seal. Your party loses gold beyond the purchase price."},"E079.3":{"s":"While the goblins are arguing about the price of the gears, you carry the bags of food behind the cart. Your supplies are replenished.","f":"One of the goblins notices the loss and whistles to his henchmen. A skirmish begins."},"E079.4":{"s":"{{heroName}} interrupts the goblin cries with one precise sentence and bargains for supplies for the gold already given.","f":"The goblins accept payment for negotiations, but do not agree to the price of {{heroName}}. The party is left without supplies."},"E079.5":{"s":"You walk around the suspicious cart without touching either the goods or the purse. The goblins argue for a long time about who missed out on the profit."},"E080.1":{"s":"The goblins take your payment and show you which planks will bear your weight. The bridge creaks, but you cross safely.","f":"Even after paying the fee, one of the boards breaks and {{affectedHeroName}} is gravely wounded. The goblins pretend that they did not promise anything.","v":{"nf":"The paid bridge sags, but among the available fighters no one is gravely wounded. Goblins do not return fees."}},"E080.2":{"s":"{{heroName}} secures the sagging chain and aligns the boards on the flooring. The goblins pay in gold for the saved bridge.","f":"{{heroName}} discovers that the load-bearing boards are rotten through and through. It is not possible to strengthen the bridge without complete reconstruction."},"E080.3":{"s":"You leap across the weakest planks and reach the far bank. The goblins count the toll they failed to collect, visibly disappointed.","f":"The jumps delay the column, and one bag of provisions falls into the river. Supplies are becoming scarce."},"E080.4":{"s":"You take a long detour and lose some of your provisions along the way. The Goblin Bridge is left behind along with its dubious guarantees."},"E081.1":{"s":"You tear off the lid of the barrel and instead of a trap you find hard coins. The Goblin inscription was clearly meant to scare away competitors.","f":"A spring mechanism under the cover is activated, and {{affectedHeroName}} is gravely wounded. The barrel crumbles without giving away the treasure.","v":{"nf":"The trap is triggered, but no one among the available fighters is gravely wounded. The coins remain inside the broken barrel."}},"E081.2":{"s":"You roll the barrel around the bend and open it away from the road. Gold is found inside.","f":"On a bump, the barrel bursts, scattering sharp pieces of iron throughout the convoy. Some of the supplies turn out to be spoiled."},"E081.3":{"s":"{{heroName}} notices a hidden lever under the hoop and disarms the trap. After this, you can safely open the barrel and take away the gold.","f":"{{heroName}} discovers too many suspicious springs beneath the lid and advises leaving it alone. You find no treasure."},"E081.4":{"s":"You pass the barrel without putting goblin honesty to the test. The ringing inside fades behind you."},"E082.1":{"s":"Your cart unexpectedly arrives first, despite the crooked wheels. The goblins reluctantly give out gold and supplies.","f":"At the last turn, the cart overturns and {{affectedHeroName}} is gravely wounded. The crowd is already cheering for the new winner.","v":{"nf":"The cart breaks at a turn, but none of the available fighters is gravely wounded. The prize remains with the opponents."}},"E082.2":{"s":"{{heroName}} straightens the cart on a dangerous descent and snatches victory. The judges issue gold and provisions.","f":"The wheel slips off the axle and {{affectedHeroName}} is gravely wounded. The goblins declare the race over.","v":{"nf":"The cart goes off the track, but among the available fighters no one is gravely wounded. Victory goes to the opponents."}},"E082.3":{"s":"You bet gold on the most confident rider and he actually finishes first. The winnings go to the treasury.","f":"The favorite gets stuck in the mud already at the start, and your bet remains with the goblin bookmakers. No winnings."},"E082.4":{"s":"You quietly loosen the fastening on someone else's cart, and your opponents go off the track. The prize gold goes to the party.","f":"The goblins notice the sabotage before the start and surround you with wrenches at the ready. A skirmish begins."},"E083.1":{"s":"The goblin cook pours stew into camp pots and accepts the agreed payment. The party's food supply increases."},"E083.2":{"s":"You try the stew, and the cook, pleased with the courage of the guests, gives another portion for the road. There are more supplies.","f":"The free sample turns out to be too dangerous for the stomach: {{affectedHeroName}} is gravely wounded. The cook hastily hides the cauldron.","v":{"nf":"The stew causes a commotion, but none of the available fighters are gravely wounded. The party does not receive free food."}},"E083.3":{"s":"{{heroName}} checks ingredients and selects safe portions. For the gold already paid, the cook gives out supplies.","f":"{{heroName}} spots something dubious in the cooking pot and refuses the purchase. The cook keeps the inspection fee."},"E083.4":{"s":"You disperse the goblins and take away the bags of food left by the cauldron. Your supplies are replenished.","f":"The cook screams and the merchants grab their carving knives. A skirmish begins."},"E084.1":{"s":"The map you bought really does lead to a hidden cache, just as the goblin promised. Inside, you find gold.","f":"The map leads to an empty pit already marked on a dozen other copies. The goblin refuses to return your coins."},"E084.2":{"s":"The goblin backs away, thrusts a map into your hands and empties his purse to be rid of you. The map is little more than a roadside curiosity, but the coins go into your treasury.","f":"The seller whistles, and his armed accomplices run out of the bushes. Instead of a map, a skirmish begins."},"E084.3":{"s":"{{heroName}} notices that the prices on the back are printed on top of the old clue and finds the real cache. Gold replenishes the treasury.","f":"The seller calls your questions an act of damage to his wares and demands a fee. You lose gold without ever testing the map."},"E084.4":{"s":"You walk past the goblin and his map before he can quote a fourth price. He immediately turns to the next travellers."},"E085.1":{"s":"You collect intact bags and coins from the wreckage of the caravan. The party replenishes supplies and gold.","f":"While you are dismantling the cargo, the raiders return from the ravine. A skirmish begins."},"E085.2":{"s":"The raiders' tracks lead to the caravan's hidden strongbox. You take the gold without meeting a single guard.","f":"The pursuit brings you to a fortified raider camp. The raiders have already spotted your party, and a battle begins."},"E085.3":{"s":"{{heroName}} inspects the ravine, finds a safe descent and points to the surviving cargo. Gold and supplies go to the party.","f":"As you descend into the ravine, an ambusher strikes. {{affectedHeroName}} is gravely wounded.","v":{"nf":"Reconnaissance discovers an ambush, but among the available fighters, no one is gravely wounded. The cargo remains in the ravine."}},"E085.4":{"s":"You leave broken carts on the road and do not follow the tracks into the ravine. The party retains its strength, but does not receive any loot."},"E086.1":{"s":"You remove old coins from the nameless altar without touching the bloody marks. The gold is sent to the treasury.","f":"As soon as you move the coins, the altar releases a sharp magical blow. {{affectedHeroName}} is gravely wounded.","v":{"nf":"Altar responds with a dangerous surge, but among the available fighters, no one is gravely wounded. The coins remain in place."}},"E086.2":{"s":"You leave gold on the altar, and a cache of travel food opens nearby. The party takes supplies.","f":"The coins vanish into the stone, but the altar gives no answer. Your offering is lost without reward."},"E086.3":{"s":"{{heroName}} recognizes the old system of hiding places in the carving and opens a niche with gold. The altar itself remains untouched.","f":"During the investigation, armed guardians emerge from behind the altar, not wanting an explanation. A skirmish begins."},"E086.4":{"s":"You smash a stone altar and find hidden coins in the base. The party gets the gold.","f":"A crack in the altar releases a call, which is answered by armed followers of an unknown force. The battle begins."},"E087.1":{"s":"You choose one of the mercenaries, hand over the payment and conclude a contract at a common fire. A new fighter joins the party.","v":{"rs":"The candidate agrees to serve, but there is no free space for a new fighter. Instead of hiring, the unit receives gold."}},"E087.2":{"s":"One of the mercenaries agrees to wait for a share of future spoils instead of immediate payment. He joins the party.","f":"The candidate rejects the promise of a share and demands compensation for his time. The party loses gold without a new fighter.","v":{"rs":"The mercenary accepts your terms, but there is no room for him in your ranks. You receive gold in place of his service."}},"E087.3":{"s":"{{heroName}} arranges bargaining between candidates and seeks agreement for the fee already paid. One mercenary joins the party.","f":"Even with {{heroName}} mediating, the candidates cannot agree on a price. The money paid for negotiations is not returned.","v":{"rs":"{{heroName}} is seeking an agreement, but there is no free space for a new recruit. Instead of replenishment, the party receives gold."}},"E087.4":{"s":"The dice fall in your favour, and the mercenaries pay out your winnings. Your stake was already in the common pot.","f":"In the last throw, the opponent throws a stronger combination. Your bet remains with the mercenaries."},"E087.5":{"s":"You don't choose a new fighter and leave the mercenaries at the fire. Their argument about the next contract can be heard for a long time."},"E088.1":{"s":"The door marked with a Pawn opens into a storeroom of travel supplies. You collect them and return down the passage.","f":"The door with the pawn leads to a littered corridor, where you have to spend some of the supplies before getting out."},"E088.2":{"s":"Behind the door marked with a Knight stands a chest of gold, left by the cavern's former owners.","f":"Armed guards emerge from the Knight's passage and cut off your retreat. A skirmish begins."},"E088.3":{"s":"The door marked with a Bishop opens onto a niche filled with gold. You snatch the treasure before the stone slab closes.","f":"The hidden plate hits when the door is opened, and {{affectedHeroName}} is severely injured.","v":{"nf":"The door slams shut with a dangerous blow, but among the available fighters no one is gravely wounded. The gold stays inside."}},"E088.4":{"s":"{{heroName}} raises the heavy door marked with a Rook, revealing a chest of gold.","f":"The weight of the stone door is too much, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The door breaks off its support, but among the available fighters no one is gravely wounded. The door remains closed."}},"E088.5":{"s":"You do not select any of the five doors. The stone signs remain waiting for the next traveler."},"E089.1":{"s":"You quickly collect the remaining coins before the hot ones burn your hands. The treasury is replenished with gold.","f":"A red-hot ingot is found among the falling coins, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The hot metal forces you back, but none of the eligible fighters is gravely wounded. The coins remain beyond reach."}},"E089.2":{"s":"You select only coins that do not produce steam and put them in a bag. The party gets the gold.","f":"Cold coins are fragile and crumble into dust as soon as you try to pick them up. Nothing of value remains."},"E089.3":{"s":"{{heroName}} finds safe spaces between falling hot coins. The party manages to collect gold.","f":"{{heroName}} is forced to stop in front of a continuous stream of hot metal. The loot remains lying on the road."},"E089.4":{"s":"You turn off the road and go around the area where metal is falling from the sky. Strange coins remain someone else's find."},"E090.1":{"s":"The owner of the fog inn accepts payment, allocates rooms and collects supplies for the journey. The party leaves the courtyard at dawn."},"E090.2":{"s":"You beat the inn's patrons at cards and scoop the gold from the table. Your stake has already been paid.","f":"Luck deserts you at the card table: your opponent holds the final trump. The gold you wagered is lost."},"E090.3":{"s":"The silent demon finally answers your question and reveals a cache of gold. The party takes the find.","f":"The demon pushes back his chair and silently signals to the inn's guards. A skirmish begins."},"E090.4":{"s":"{{heroName}} collects stories from guests and uses them to find a small supply of travel food. Your supplies are replenished.","f":"{{heroName}} hears five different versions of the same story and cannot separate truth from fiction. The party leaves without useful information."},"E090.5":{"s":"You do not enter an unfamiliar inn. After a few turns, the hotel lights disappear behind the fog."},"E091.1":{"s":"You occupy an empty signal tower until unfamiliar warriors arrive. In the guard niche there is gold left by the former garrison.","f":"Armed silhouettes reach the tower before you and block the stairs. A skirmish begins."},"E091.2":{"s":"You establish a defensive position and find provisions in the tower. But armed detachments are approaching, and a battle begins.","f":"The bell continues to call to the warriors as the party unsuccessfully fortifies the tower. The battle begins before the defense is ready."},"E091.3":{"s":"{{heroName}} secures the tower gate and discovers gold under the old flooring. Before the armed silhouettes arrive, the party manages to leave.","f":"{{heroName}} does not have time to close all the approaches, and the soldiers enter the lower tier. The battle begins."},"E091.4":{"s":"You move away from the tower before the troops appear. The self-ringing bell can be heard for a long time behind the hills."},"E092.1":{"s":"You cross a stream of red sand and reach chests on the far bank. One of them is filled with gold.","f":"The moving sand collapses underfoot, and {{affectedHeroName}} is gravely wounded. You can't get to the chests.","v":{"nf":"The red sand drags the party back to the shore, but none of the available fighters are gravely wounded. Chests remain inaccessible."}},"E092.2":{"s":"You spend supplies on ropes and supports for the crossing. Beyond the stream of red sand, you recover the gold.","f":"Preparation does not help: the supports go into the red sand, and the path to the chests is closed. Spent supplies cannot be returned."},"E092.3":{"s":"{{heroName}} assembles a stable deck over moving sand. On the other side, the party finds gold and surviving provisions.","f":"{{heroName}} discovers that the bank is too loose for supports. It is not possible to build a crossing."},"E092.4":{"s":"You walk up the riverbed in search of a dry sandbank. There is a bypass, but the extra journey takes up supplies."},"E093.1":{"s":"You go down into an old well and find a man who couldn't get out on his own. The rescued one agrees to join the party.","f":"At the bottom, instead of a prisoner, you are met by armed inhabitants of the dungeon. A skirmish begins.","v":{"rs":"You pull a prisoner out of the well, but fail to accept him into the party. In gratitude, the rescued person gives gold."}},"E093.2":{"s":"A strong tug responds to your rope, and soon an exhausted traveler emerges from the well. He decides to go with the party.","f":"The rope is pulled out empty, but the voice no longer responds. The long rescue attempt consumes supplies.","v":{"rs":"The traveler gets out along the rope, but there is no free space for him. He leaves gold for the saviors."}},"E093.3":{"s":"{{heroName}} goes down first, finds the prisoner and takes him out along with the old purse. The rescued person joins the party, and gold replenishes the treasury.","f":"In the darkness of the well, an unseen blow gravely wounds {{affectedHeroName}}. The rescue fails.","v":{"rs":"{{heroName}} takes the prisoner out and finds his purse, but the new fighter cannot join the party. The gold still goes to the saviors.","nf":"Exploration of the well is disrupted, but among the available fighters no one is gravely wounded. The caller remains below."}},"E093.4":{"s":"You throw stones into the well and cover the mouth with debris. The voice is no longer heard, and the party continues on its way."},"E094.1":{"s":"You place gold coins in the indentations of the statue's fingers. A niche with supplies opens under the palm.","f":"The statue accepts the offering, but its palm does not move. No supplies are revealed, and your gold remains in the stone recesses."},"E094.2":{"s":"After the generous offering, the palm of the statue lowers and reveals a large storage room. The party takes supplies.","f":"The statue only gives out a tiny bundle of provisions, although you left a lot of gold. The large storage room remains closed."},"E094.3":{"s":"You pull the old coins out of the recesses of the stone palm before it can close. The loot replenishes the treasury.","f":"The palm turns and armed guardians emerge from the base of the statue. A skirmish begins."},"E094.4":{"s":"{{heroName}} reads the dedication on the pedestal and finds a hidden door at the feet of the statue. Behind it lie gold and supplies.","f":"{{heroName}} distinguishes only fragments of dedication, which are not enough to open the cache. The party leaves with nothing."},"E094.5":{"s":"You walk past the open stone palm, leaving nothing and taking nothing. The statue remains motionless."},"E095.1":{"s":"The first camp accepts your support and pays the agreed gold for the assistance provided. The party leaves the field before the clash of armies.","f":"The neighbors of the first camp consider you part of its forces and come forward to meet you. A skirmish begins."},"E095.2":{"s":"The commanders of the second camp agree to pay for your support and give away the gold. While the others are arguing, the party manages to leave.","f":"Choosing the second banner draws you into a clash between the other two camps. The battle begins."},"E095.3":{"s":"The third camp pays most handsomely for your allegiance. The gold enters your treasury before the opposing armies clash.","f":"The first two camps unite against their rival's new ally. The battle begins."},"E095.4":{"s":"{{heroName}} seats three commanders at one table and achieves a truce. For mediation, the party receives gold and supplies.","f":"One of the commanders breaks down the negotiations and leads his soldiers to your party. A skirmish begins."},"E095.5":{"s":"You do not accept anyone's banner and pass between camps before nightfall. The dispute between the three commanders is left behind."},"E096.1":{"s":"The king sits on the empty throne, and a casket of gold slides out from the armrests. The party takes the find.","f":"The back of the throne contracts around the King, leaving a severe wound. The ancient mechanism releases him only after a long struggle.","v":{"nf":"The throne tries to bind the King, but fails to inflict a grave wound. The casket remains shut."}},"E096.2":{"s":"The king puts on a crown without a coat of arms, and a vault opens at the base of the throne. The party takes gold and supplies.","f":"The crown fuses with the King's temples and takes his life. With the death of the King, the journey ends.","v":{"nf":"The crown rejects the King without killing him. The throne's treasures remain sealed."}},"E096.3":{"s":"{{heroName}} finds a hidden seam on the lower edge of the throne and removes the casket of gold without touching the crown.","f":"When {{heroName}} examines the carving, the throne ejects a sharp shard. {{affectedHeroName}} is gravely wounded.","v":{"nf":"The throne lashes out with a razor-sharp shard, but none of the eligible fighters is gravely wounded. The casket remains hidden."}},"E096.4":{"s":"You break the crown on the seat and find a gold frame inside. Its cost replenishes the treasury.","f":"The crown is resistant to impacts, and its surface heals cracks. The party does not receive any loot."},"E096.5":{"s":"You leave both the crown and the empty throne untouched. Soon there is not even a trace of them left on the road."},"E097.1":{"s":"You place the coins on the counter, which is only visible out of the corner of your eye. Instead, a package of supplies appears.","f":"The invisible merchant collects the payment and then demands the same amount for a non-existent delivery. The party loses additional gold and is left without supplies."},"E097.2":{"s":"You leave a fee and ask to send a companion; a mercenary emerges from the void, agreeing to serve the party.","f":"The coins vanish, but no mercenary appears. The market's disembodied voice demands another fee to cancel your order, costing you still more gold.","v":{"rs":"The invisible market accepts your order, but cannot provide a new fighter. It refunds part of the fee in gold."}},"E097.3":{"s":"{{heroName}} feels the border of the enchantment and discovers where the merchants hide the real wallets. The party receives gold.","f":"{{heroName}} sees only reflections of counters that disappear when you try to approach. There is no find."},"E097.4":{"s":"You intercept the invisible purse before it disappears under the counter. There is gold in it.","f":"An alarm bell rings behind an invisible counter, and armed market guards block the way. A skirmish begins."},"E097.5":{"s":"You do not leave coins where the merchant is not visible. The market voices fade away after a few steps."},"E098.1":{"s":"You cling to the ledges of the stonework and reach the illuminated window. There is gold in the upper room.","f":"One of the ledges breaks off, and {{affectedHeroName}} is gravely wounded when falling. The light above doesn't go out.","v":{"nf":"The ledge breaks, but no one among the available fighters is gravely wounded. It is not possible to get inside the tower."}},"E098.2":{"s":"{{heroName}} notices a fragile slab at the base of the tower and opens a passage to a storage room with gold.","f":"The masonry collapses before {{heroName}} can strengthen it, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The weak masonry crumbles, but among the available fighters no one is gravely wounded. The passage remains closed."}},"E098.3":{"s":"{{heroName}} finds an invisible doorway in the wall's shadow and opens it with a magical sign. You take gold and supplies from the tower.","f":"{{heroName}} walks around the tower several times, but the magical entrance never appears. The unit receives no loot."},"E098.4":{"s":"You break part of the wall with the whole party and get to the chest with gold. The tower is left with a gaping hole.","f":"The blows awaken the tower guards, who come out of the breach with weapons. The battle begins."},"E098.5":{"s":"You leave the tower standing without a door in the middle of an empty plain. The light at its top continues to burn."},"E099.1":{"s":"You carefully collect the sealed bags by the fire. They contain supplies suitable for the road.","f":"As soon as you lift the last bag, armed pursuers of the missing party emerge from the darkness. A skirmish begins."},"E099.2":{"s":"The folded equipment reveals a travel treasury. The gold goes to your party.","f":"When you reach for the pouch, the trap hidden in the cloak is triggered, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The trap in the equipment is triggered, but among the available fighters no one is gravely wounded. The gold remains by the fire."}},"E099.3":{"s":"{{heroName}} notices drag marks behind the fire and finds supplies and gold hidden to the side.","f":"{{heroName}} finds signs of an ambush, but armed pursuers are already nearby. A skirmish begins."},"E099.4":{"s":"You hide by an abandoned fire and intercept the purse of the returning robber. The party gets the gold.","f":"An entire armed gang, not merely a lone traveller, arrives at the campfire. Your ambush turns into a battle."},"E099.5":{"s":"You don't disassemble other people's equipment or try to find out the fate of the missing. The fire remains burning behind."},"E100.1":{"s":"You leave gold on the glowing stones and the trail calms down. As a reward, the road opens a cache of supplies."},"E100.2":{"s":"You offer provisions to the road, and an old purse of gold appears among the stones. You collect the strange payment."},"E100.3":{"s":"You let the road choose one of the fighters, but the lights go out without causing harm. Instead of blood, the stones reveal gold.","f":"Stones flare up under {{affectedHeroName}}'s feet, leaving a serious wound. There is no promised gold.","v":{"nf":"Glowing stones require sacrifice, but among the available fighters, no one is gravely wounded. Gold doesn't appear."}},"E100.4":{"s":"The king accepts the challenge of the road, and the light opens before his steps. The stones reveal gold and supplies.","f":"The stones respond to the challenge with a fatal blow, and the King dies. His journey ends here.","v":{"nf":"The road rejects the challenge, but the King remains alive. Gold and supplies do not appear."}},"E100.5":{"s":"You refuse to pay the road any tribute, and it raises armed guardians against you. A battle begins."}});
export { OUTCOMES_EN_E051_E100 };
